/* eslint-disable max-len */
/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isValidGlyph = require( './utils/is-valid-glyph.js' );
var isValidRowCol = require( './utils/is-valid-row-col.js' );

/**
* Method to add glyph.
*
* @private
* @name setGlyph
* @param {number} row - row number
* @param {number} col - col number
* @param {string} glyph - glyph name
* @param {boolean} overwrite - overwrite
* @param {boolean} safeArea - safeArea
* @returns {void}
*/
function setGlyph( row, col, glyph, overwrite, safeArea ) {
	var a;
	var b;
	var r;
	var c;

	r = row;
	c = col;
	if ( safeArea ) {
		r = this.getSafeRow( row );
		c = this.getSafeColumn( col );
	}
	a = ( isValidRowCol( r, c, this._height, this._width ) && isValidGlyph( glyph ) );

	// If glyph is already set to default we can change it
	b = a && ( overwrite || this._glyphMatrix[ r ][ c ] === this._glyph );

	if ( b ) {
		this._glyphMatrix[ r ][ c ] = glyph;
	}
}

module.exports = setGlyph;
